new_rows=[]; deltas=[]

def whole(gid, cid, td,te, ed,ee, fd,fe, md,me, criteria, mode='analysis', checks=None):
    brief=dict(id=cid,taskDemandDe=td,taskDemandEn=te,expectedPerformanceDe=ed,expectedPerformanceEn=ee,understandingFocusDe=fd,understandingFocusEn=fe)
    row=dict(goalId=gid,case=brief,
        assessmentMethodDe='Bewertung der selbstständig vorgelegten Leistung anhand der Kriterien. Modellantwort und synthetische Daten belegen das Aufgabendesign; sie sind keine beobachtete Lernendenleistung.',
        assessmentMethodEn='Assess the independently submitted performance against the criteria. Model answers and synthetic data establish the task design; they are not observed learner performance.',
        rubric=dict(maximumPoints=len(criteria),criteria=[dict(points=1,aspectDe=d,aspectEn=e) for d,e in criteria],fullCreditEvidenceDe=ed,fullCreditEvidenceEn=ee,misconceptionChecks=checks or []),
        materialAndData=dict(de=md,en=me),
        evidenceMode=mode,syntheticFixture=(mode=='synthetic_analysis'),
        observedLearnerWork=None,humanApproval=False,humanTrial=False)
    new_rows.append(row)
    return brief

def add(gid, brief, expid):
    profiles[gid]['applicationCaseBriefs'].append(brief)
    profiles[gid]['expectations'].append(dict(id=expid,essentialUnderstandingDe=brief['understandingFocusDe'],essentialUnderstandingEn=brief['understandingFocusEn'],observablePerformanceDe=brief['expectedPerformanceDe'],observablePerformanceEn=brief['expectedPerformanceEn']))
    profiles[gid]['coverageExpectations']['requiredExpectationIds'].append(expid)
    deltas.append(dict(goalId=gid,action='add_whole_case',caseId=brief['id'],expectationId=expid))

def replace(gid, brief, expid):
    ix=next(j for j,x in enumerate(profiles[gid]['applicationCaseBriefs']) if x['id']==brief['id'])
    profiles[gid]['applicationCaseBriefs'][ix]=brief
    exp=next(x for x in profiles[gid]['expectations'] if x['id']==expid)
    exp.update(essentialUnderstandingDe=brief['understandingFocusDe'],essentialUnderstandingEn=brief['understandingFocusEn'],observablePerformanceDe=brief['expectedPerformanceDe'],observablePerformanceEn=brief['expectedPerformanceEn'])
    deltas.append(dict(goalId=gid,action='replace_only_incomplete_whole_case',caseId=brief['id'],expectationId=expid))

# Existing controlled denaturation and salting-out cases stay exactly as authored.
g=IDS[0]
md='Synthetische, nicht im Labor erhobene Daten. Alle Aktivitätsmessungen erfolgen nach der Vorbehandlung bei gleicher Enzymmenge, gleichem Substratüberschuss, pH und gleicher Messtemperatur. Lactase: Vorbehandlung 20 °C/5 min -> 10 µmol Lactoseabbau pro min; 80 °C/5 min, danach auf 37 °C gekühlt -> 1 µmol/min; ohne Enzym -> 0 µmol/min; Assay stets pH 7/37 °C. Waschmittelprotease: Vorbehandlung 30 °C/5 min -> 12 µmol gespaltener Peptidbindungen pro min; 80 °C/5 min, danach auf 30 °C gekühlt -> 2 µmol/min; ohne Enzym -> 0 µmol/min; Assay stets pH 8/30 °C. Im Modell sind Proteine nach Hitze teilweise entfaltet/aggregiert; Löslichkeitsänderung allein ist kein Aktivitätsnachweis.'
me='Synthetic data, not collected in a laboratory. After pretreatment, all assays use equal enzyme amounts, excess substrate, equal pH and equal assay temperature. Lactase: pretreatment at 20 °C for 5 min -> 10 µmol lactose hydrolysed per min; 80 °C for 5 min, then cooled to 37 °C -> 1 µmol/min; no enzyme -> 0 µmol/min; assays at pH 7/37 °C. Detergent protease: pretreatment at 30 °C for 5 min -> 12 µmol peptide bonds cleaved per min; 80 °C for 5 min, then cooled to 30 °C -> 2 µmol/min; no enzyme -> 0 µmol/min; assays at pH 8/30 °C. In this model heat partly unfolds/aggregates the proteins; a solubility change alone does not measure activity.'
b=whole(g,'enzyme-function-metabolism-detergent',
    'Werte die ausdrücklich synthetischen Lactase- und Waschmittelprotease-Daten aus: '+md+' Berechne den Aktivitätsverlust nach Hitze, erkläre ihn über die Proteinstruktur und leite eine Folge für Lactoseverdauung und Entfernung von Eiweißflecken ab. Begründe, warum Abkühlen keine sichere Wiederherstellung der Wirkung und Trübung allein keine Enzyminaktivität beweist.',
    'Evaluate the explicitly synthetic lactase and detergent-protease data: '+me+' Calculate loss of activity after heat, explain it through protein structure and infer a consequence for lactose digestion and removal of protein stains. Explain why cooling does not guarantee restored activity and turbidity alone does not prove enzyme inactivity.',
    'Lactase verliert im Modell 90 %, Protease etwa 83 % Aktivität. Da bei gleicher Messtemperatur und gleichen Kontrollen gemessen wird, ist der verbleibende Unterschied kein bloßer aktueller Temperatureffekt. Veränderte Faltung/aktives Zentrum kann Substratbindung und Katalyse schwächen; Aggregation kann beitragen. Weniger Lactase verlangsamt Lactosehydrolyse im Verdauungskontext, weniger Protease den Eiweißabbau im Waschmittel. Kein Enzym wirkt auf jedes Substrat; die Protease ist keine Lactase. Abkühlen kann irreversible Strukturänderungen nicht sicher rückgängig machen. Für ein anderes Enzym oder Waschmittel muss die Stabilität geprüft werden; aus Trübung allein folgt kein Aktivitätswert.',
    'Lactase loses 90 % and protease about 83 % activity in the model. Equal assay temperature and valid controls exclude a mere difference in current assay temperature. Altered folding/active-site shape can weaken substrate binding and catalysis; aggregation may contribute. Lower lactase activity slows lactose hydrolysis in digestion, while lower protease activity slows protein-stain breakdown in detergent. Enzymes are substrate-selective; protease is not lactase. Cooling does not reliably reverse irreversible structural changes. Other enzymes/detergents need their own stability checks; turbidity alone gives no activity value.',
    'Proteinstruktur und kontrolliert gemessene Aktivität verbinden und auf Stoffwechsel sowie Waschmittel übertragen.',
    'Connect protein structure with controlled measured activity and transfer to metabolism and detergents.',md,me,
    [('Beide Aktivitätsverluste korrekt berechnen.','Calculate both activity losses correctly.'),('Gleiche Messbedingungen und enzymfreie Kontrollen nutzen.','Use equal assay conditions and enzyme-free controls.'),('Faltung/aktives Zentrum mit Aktivität verknüpfen.','Relate folding/active site to activity.'),('Lactoseverdauung und Eiweißfleckenabbau jeweils ableiten.','Infer effects on lactose digestion and protein-stain breakdown.'),('Löslichkeit, Aktivität und Reversibilität mit Schlussgrenzen unterscheiden.','Distinguish solubility, activity and reversibility with bounded inferences.')],mode='synthetic_analysis')
add(g,b,'enzyme-effects')

# A complete nutrient structure/function comparison closes the selected fat/protein gap.
g=IDS[1]
md='Autoren-Strukturkarten: T = Glycerin mit drei über Ester gebundenen langkettigen Fettsäureresten; P = lange Aminosäurekette mit -CO-NH- und variablen Seitenketten; G = Glucose mit mehreren OH-Gruppen und zugänglicher Carbonylform; C = Ascorbinsäure (organisches Vitamin); Ca = Calciumionen aus einem Salz. Keine Karte bildet den gesamten Bedarf einer Person ab.'
me='Author-created structure cards: T = glycerol carrying three long fatty-acid residues through ester bonds; P = a long amino-acid chain with -CO-NH- links and variable side chains; G = glucose with several OH groups and an accessible carbonyl form; C = ascorbic acid (an organic vitamin); Ca = calcium ions from a salt. No card describes a person\'s complete nutrient requirements.'
b=whole(g,'selected-nutrients-all-functions',
    md+' Vergleiche die Stoffklassen anhand der Karten, ordne Makro-/Mikronährstoffe zu und beschreibe für jeden der fünf ausgewählten Inhaltsstoffe eine konkrete Körperfunktion. Erkläre insbesondere die Bedeutung des Fettes als Energiereserve und von Nahrungsprotein als Aminosäurelieferant. Prüfe die Behauptungen jedes Fett ist ein Membranbaustein und jedes Nahrungsprotein ist ein Enzym.',
    me+' Compare classes using the cards, assign macro-/micronutrients and describe a concrete bodily function of each selected component. In particular explain fat as an energy store and dietary protein as an amino-acid source. Assess the claims that every fat is a membrane component and every dietary protein is an enzyme.',
    'T ist ein Triacylglycerid/Makronährstoff: langkettige Reste ermöglichen energiereiche Speicherung; nach Abbau liefert es Energie. Es ist nicht mit amphiphilen Membranphospholipiden gleichzusetzen. P ist Protein/Makronährstoff: Verdauung liefert Aminosäuren zum Aufbau körpereigener Proteine, etwa Muskel- oder Enzymproteine; aufgenommenes Protein wird nicht unverändert als Enzym eingebaut. G ist Kohlenhydrat/Makronährstoff und dient der Energiebereitstellung. C ist Vitamin C/Mikronährstoff und unterstützt Enzyme der Kollagenbildung. Ca ist Mineralstoff/Mikronährstoff und Bestandteil der mineralischen Knochen-/Zahnhartsubstanz. Bedarfsmengen statt Molekülgröße unterscheiden Makro und Mikro; verschiedene Stoffklassen besitzen verschiedene Bindungen und Bausteine.',
    'T is a triacylglycerol/macronutrient: long-chain residues allow energy-rich storage; breakdown provides energy. It must not be equated with amphiphilic membrane phospholipids. P is a protein/macronutrient: digestion supplies amino acids to build body proteins such as muscle proteins or enzymes; dietary protein is not inserted unchanged as an enzyme. G is a carbohydrate/macronutrient used for energy. C is vitamin C/a micronutrient supporting enzymes of collagen formation. Ca is a mineral/micronutrient forming part of mineralised bone/tooth tissue. Required amounts, not molecular size, distinguish macro from micro; classes differ in bonds and units.',
    'Alle ausgewählten Inhaltsstoffe strukturell vergleichen und ihre jeweils konkrete Körperfunktion nennen.',
    'Compare all selected components structurally and give their respective concrete bodily functions.',md,me,
    [('Strukturmerkmale von Fett, Protein und Kohlenhydrat vergleichen.','Compare structural features of fat, protein and carbohydrate.'),('Makro/Mikro ohne Molekülgrößenregel einordnen.','Classify macro/micro without a molecular-size rule.'),('Fettfunktion mit Triacylglyceridstruktur und Membranabgrenzung erklären.','Explain fat function from triacylglycerol structure and distinguish membrane lipids.'),('Protein als Aminosäurelieferant mit konkreter Körperfunktion erklären.','Explain protein as an amino-acid source with a concrete bodily function.'),('Glucose-, Vitamin-C- und Calciumfunktion korrekt angeben.','Correctly state glucose, vitamin-C and calcium functions.')])
add(g,b,'all-selected-body-functions')

# Carbohydrate units/bonds and biological roles are a genuine part of the comparison.
g=IDS[2]
md='Autoren-Strukturkarten: DNA = Desoxyribose-Phosphat-Kette mit A,T,G,C; RNA = Ribose-Phosphat-Kette mit A,U,G,C; Stärke = alpha-glycosidisch verknüpfte Glucoseeinheiten; Cellulose = beta(1->4)-verknüpfte Glucoseeinheiten; Protein = Aminosäuren mit Peptidbindungen; Fett = Glycerin mit drei Fettsäureresten über Esterbindungen. Für den Transfer: X besitzt eine Zucker-Phosphat-Kette und Uracil, Y nur beta(1->4)-Glucoseeinheiten.'
me='Author-created structure cards: DNA = deoxyribose-phosphate chain carrying A,T,G,C; RNA = ribose-phosphate chain carrying A,U,G,C; starch = alpha-glycosidically linked glucose units; cellulose = beta(1->4)-linked glucose units; protein = amino acids linked by peptide bonds; fat = glycerol bearing three fatty-acid residues through ester bonds. Transfer: X has a sugar-phosphate chain and uracil, Y has only beta(1->4)-linked glucose units.'
b=whole(g,'whole-biomolecule-carbohydrate-comparison',
    md+' Vergleiche Nukleinsäuren ausdrücklich mit Kohlenhydraten, Proteinen und Fetten nach Bausteinen, Bindungen und biologischer Funktion. Unterscheide Stärke und Cellulose trotz gleicher Monomerklasse. Ordne X/Y anhand positiver Strukturmerkmale ein und begründe, weshalb ein langes Glucosepolymer keine Nukleinsäure ist.',
    me+' Explicitly compare nucleic acids with carbohydrates, proteins and fats by units, linkages and biological function. Distinguish starch and cellulose despite their shared monomer class. Classify X/Y from positive features and explain why a long glucose polymer is not a nucleic acid.',
    'DNA/RNA bestehen aus Nucleotiden mit Zucker, Phosphat und Base, verbunden über Phosphodiesterbindungen. Die Basensequenz trägt genetische Information; DNA speichert sie, verschiedene RNA-Typen wirken etwa bei ihrer Umsetzung in Proteine mit. Stärke und Cellulose sind glycosidisch verknüpfte Glucosepolymere: Stärke dient pflanzlicher Energiespeicherung, Cellulose der Zellwandstruktur; die Bindungsgeometrie beeinflusst die Funktion. Proteine besitzen Peptidbindungen und etwa katalytische/strukturelle Funktionen, Triacylglyceride drei Esterbindungen und Energiespeicherfunktion. X ist RNA, Y Cellulose; beiden gemeinsam ist eine Kette, aber Y fehlen Nucleotid-Basen und Zucker-Phosphat-Rückgrat. Molekülgröße allein beweist keine Informationscodierung.',
    'DNA/RNA contain sugar-phosphate-base nucleotides linked by phosphodiester bonds. Base sequence carries genetic information; DNA stores it and various RNA types participate, for example, in its translation into proteins. Starch and cellulose are glycosidically linked glucose polymers: starch stores energy in plants, cellulose structures cell walls; linkage geometry affects function. Proteins have peptide bonds and catalytic/structural functions; triacylglycerols have three ester links and store energy. X is RNA and Y cellulose; both are chains, but Y lacks nucleotide bases and a sugar-phosphate backbone. Size alone does not establish information coding.',
    'Bausteine und Bindungen mit Informations-, Speicher- und Strukturfunktionen vergleichen, einschließlich Kohlenhydraten.',
    'Compare units and bonds with information, storage and structural functions, explicitly including carbohydrates.',md,me,
    [('DNA/RNA-Bausteine und Phosphodiesterbindungen benennen.','Identify DNA/RNA units and phosphodiester bonds.'),('Kohlenhydratstruktur einschließlich Stärke/Cellulose vergleichen.','Compare carbohydrate structures including starch/cellulose.'),('Fett und Protein als weitere Vergleichsklassen korrekt einordnen.','Correctly include fat and protein as further comparison classes.'),('Alle Klassen mit konkreten biologischen Funktionen verbinden.','Connect all classes to concrete biological functions.'),('X/Y anhand Struktur statt Größe zuordnen und Grenze erklären.','Classify X/Y from structure rather than size and explain the limit.')])
add(g,b,'carbohydrate-structure-function-comparison')

# Actual solvent choice in food preparation, with data included in the profile brief.
g=IDS[3]
md='Synthetische Küchenmodell-Daten bei 20 °C, gleiche Stoffmenge/Volumen: Kochsalz löst sich klar in Wasser, bleibt in Speiseöl ungelöst; beta-Carotin aus einem Möhrenextrakt färbt Öl deutlich, Wasser kaum; Lecithin besitzt einen polaren Phosphat-Kopf und unpolare Kohlenwasserstoffreste und stabilisiert beim Rühren Öl/Wasser-Tröpfchen. Salz besitzt Ionen, beta-Carotin überwiegend unpolare C-H-Bereiche. Nur lebensmitteltaugliches Wasser und Speiseöl stehen zur Auswahl. Begleittext: Vitamin C ist wasserlöslich; lipophile Vitamine benötigen geeignete Fett-/Transportbedingungen. Aufnahme, Speicherung und Ausscheidung hängen zusätzlich von Transport und Stoffwechsel ab.'
me='Synthetic kitchen-model data at 20 °C using equal amounts/volumes: salt dissolves clearly in water but remains undissolved in edible oil; beta-carotene from carrot extract colours oil strongly but water only weakly; lecithin has a polar phosphate head and nonpolar hydrocarbon residues and stabilises stirred oil/water droplets. Salt contains ions, beta-carotene mainly nonpolar C-H regions. Only food-grade water and edible oil are options. Background: vitamin C is water-soluble; lipophilic vitamins need suitable fat/transport conditions. Uptake, storage and excretion additionally depend on transport and metabolism.'
b=whole(g,'food-preparation-solvent-choice',
    md+' Du bereitest eine wässrige Salzlake und ein gefärbtes Möhrenöl zu. Wähle für beide das geeignete Lösemittel und begründe mit Teilchenstruktur und Befunden. Erkläre den Einsatz von Lecithin in einer Öl/Wasser-Soße. Übertrage die Einordnung auf Vitaminaufnahme und widerlege die absolute Aussage fettlöslich bedeutet immer lange gespeichert.',
    me+' You prepare an aqueous brine and coloured carrot oil. Select the solvent for each and justify it through particle structure and observations. Explain lecithin in an oil/water sauce. Transfer the classification to vitamin uptake and reject the absolute claim that fat-soluble always means long-term storage.',
    'Für die Salzlake Wasser: polare Wassermoleküle hydratisieren die Ionen durch Ion-Dipol-Wechselwirkungen. Für beta-Carotin-Extraktion Speiseöl: große unpolare Bereiche ermöglichen passende Wechselwirkungen mit Öl; Wasser ist für diesen Zweck ungeeignet. Lecithin ist amphiphil und kann Grenzflächen stabilisieren, ohne Öl und Wasser zu einem einheitlichen molekularen Lösemittel zu machen. Wasserlösliches Vitamin C hat andere Transport-/Ausscheidungsbedingungen als lipophile Vitamine; Fettresorption und geeignete Transportstrukturen unterstützen letztere. Polarität allein legt weder individuelle Verweildauer noch Dosierung fest. Die konkreten Modellbefunde gelten nicht für jeden Farbstoff oder jedes Vitamin.',
    'Choose water for brine: polar water molecules hydrate ions through ion-dipole interactions. Choose edible oil for beta-carotene extraction: large nonpolar regions permit compatible interactions with oil; water is unsuitable for that purpose. Lecithin is amphiphilic and can stabilise interfaces without turning oil and water into a single molecular solvent. Water-soluble vitamin C has different transport/excretion conditions from lipophilic vitamins; fat uptake and suitable transport structures support the latter. Polarity alone specifies neither individual residence time nor dosage. These model observations do not apply to every pigment or vitamin.',
    'Geeignete Lösemittel in konkreter Zubereitung wählen und chemisch begründen; Vitamin-Aussagen begrenzen.',
    'Choose and chemically justify solvents for actual food-preparation purposes; bound vitamin claims.',md,me,
    [('Wasser für Salzlake auswählen und Hydratation erklären.','Select water for brine and explain hydration.'),('Öl für beta-Carotin auswählen und unpolare Bereiche nutzen.','Select oil for beta-carotene and use nonpolar regions.'),('Lecithin amphiphil und Emulsionswirkung begrenzt erklären.','Explain amphiphilic lecithin and bound its emulsifying action.'),('Resorption und Verweildauer mit zusätzlichen Bedingungen erklären.','Explain uptake and residence time using additional conditions.')],mode='synthetic_analysis')
add(g,b,'food-solvent-choice')

