dump(OUT/'cases/P9-updated-and-retained-whole-DEEN.cases-material-rubrics.json',cases)
dump(OUT/'cases/P9-only.updated-whole-DEEN.cases-material-rubrics.json',dict(schemaVersion=1,evidenceLevel='E1',maximumClaimScope='G1',goalIds=IDS,cases=[r for r in cases['cases'] if r['goalId'] in IDS],completedLearnerExecutions=0,humanApprovals=0,humanTrials=0))
reason='Gezielte Autorenkorrektur der neun versiegelten P-Befunde durch nutzbare DE/EN-Ganzfälle, Materialdaten und Kriterien. E1/G1; keine unabhängige Annahme, Labordurchführung, Lernendenleistung, HumanApproval oder HumanTrial behauptet.'
candidate=dict(schemaVersion=1,authoringContract='positive-understanding-evidence-candidates-v1',reviewId='chemie-q2-naturstoffe-p9-targeted-author-20261012-v3',reviewedAt=NOW,reviewer='Codex chemistry P9 author; informed by sealed independent A/B findings, new independent acceptance pending',goals=[dict(goalId=i,reason=reason,evidenceLevel='E1',maximumClaimScope='G1',dissent=[],profile=profiles[i]) for i in IDS])
